@KafkaListener(topics = "customer-name-changed")
public void onCustomerNameChanged(CustomerNameChangedEvent event) {
    // Denormalized copy lives on every order row for that customer.
    // Update it here instead of joining at read time.
    orderRepository.updateDenormalizedCustomerName(
        event.getCustomerId(),
        event.getNewName()
    );
}

